import{_ as u,o as i,c as n,ag as t}from"./chunks/framework.D9ghT4bC.js";const d=JSON.parse('{"title":"Unique 替换流程","description":"","frontmatter":{},"headers":[],"relativePath":"zh/Developers/Unique-replacement-process.md","filePath":"zh/Developers/Unique-replacement-process.md"}'),l={name:"zh/Developers/Unique-replacement-process.md"};function o(a,e,r,s,p,q){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="unique-替换流程" tabindex="-1">Unique 替换流程 <a class="header-anchor" href="#unique-替换流程" aria-label="Permalink to &quot;Unique 替换流程&quot;">​</a></h1><p>我们经常想改写某个 Unique，或给它加一个扩展用途的参数。</p><p>但我们得给模组制作者留出时间，让他们把旧 unique 换成新的。 这意味着会有一段重叠期——通常约一个&quot;完整小版本&quot;，即 20 个版本，大约 2.5 个月。 在此期间，新旧 unique 都必须能工作；过了这段时间，我们就应该能找到旧 unique 并妥善地消灭它。</p><p>流程如下：</p><ul><li>把旧 unique 重命名为 <code>&quot;&lt;old-unique-name&gt;Old&quot;</code>（包括 uniques 内的引用，shift+f6）</li><li>在旧 unique 正上方创建新 unique，使用旧名字</li><li>凡是使用旧 unique 的地方<strong>加上新 unique</strong>，而不是替换</li><li>给旧 unique 加 @Deprecated 注解，带替换文本——这能让模组制作者自动把旧 unique 替换成新的 <ul><li>弃用级别必须是 <code>DeprecationLevel.WARNING</code>——或者干脆不写级别，因为默认就是这个</li></ul></li></ul><p>时间过去之后，我们要：</p><ul><li>把带弃用注解的旧 unique 移到 &quot;deprecated and removed&quot; 区块的最顶部，按时间倒序排列</li><li>从代码中删除旧 unique 的所有使用</li><li>把弃用级别改为 ERROR（这样我们就无法再引入旧用法）</li></ul>',7)])])}const _=u(l,[["render",o]]);export{d as __pageData,_ as default};
